/* Generated by `pnpm kit:gen` (kit/compile.ts) from kit/fields/zen.ts: edit that file, never this one.
   zenField, the effect's kernel, in GLSL ES 3.00 (the player, the WebGL page) and in WGSL (the WebGPU page),
   and its cost an evaluation. */
export const KERNEL_GLSL = `uniform vec4 uK_rake[5];
uniform vec4 uK_stone[9];
uniform vec4 uKF[1];

float k_zenOval(float dx, float dy, float xx, float yy, float xy) {
  return dx * (dx * xx + dy * xy) + dy * dy * yy;
}

float k_zenLump(float dx, float dy, float ax, float ay, float q) {
  float p = ax * dx + ay * dy;
  return p * p * p / (q + 0.000001);
}

float k_zenUnion(float d, float r, float k0, float k1) {
  float m = min(d, r);
  float k = k0 + k1 * m;
  float h = max(0.0, k - abs(d - r));
  return m - h * h / (4.0 * k);
}

float kfield(float x, float y) {
  float v = uK_rake[0].x * x + uK_rake[0].y * y + uK_rake[0].z;
  float slow = cos(uKF[0].y) - uK_rake[4].x;
  float d = sqrt(v * v + uK_rake[0].w) + uK_rake[1].x + uK_rake[3].w * slow;
  float swell = cos(uKF[0].z);
  float dx = x - uK_stone[0].x;
  float dy = y - uK_stone[0].y;
  float q = k_zenOval(dx, dy, uK_stone[0].w, uK_stone[1].x, uK_stone[1].y);
  float ring = sqrt(q) - uK_stone[0].z;
  float core = ring + k_zenLump(dx, dy, uK_stone[1].z, uK_stone[1].w, q);
  float slope = uK_stone[2].x;
  float top = uK_stone[2].y;
  d = k_zenUnion(d, ring - uK_stone[2].z * swell, uK_rake[1].y, uK_rake[1].z);
  dx = x - uK_stone[2].w;
  dy = y - uK_stone[3].x;
  q = k_zenOval(dx, dy, uK_stone[3].z, uK_stone[3].w, uK_stone[4].x);
  ring = sqrt(q) - uK_stone[3].y;
  float e = ring + k_zenLump(dx, dy, uK_stone[4].y, uK_stone[4].z, q);
  if (e < core) {
    core = e;
    slope = uK_stone[4].w;
    top = uK_stone[5].x;
  }
  d = k_zenUnion(d, ring - uK_stone[5].y * swell, uK_rake[1].y, uK_rake[1].z);
  dx = x - uK_stone[5].z;
  dy = y - uK_stone[5].w;
  q = k_zenOval(dx, dy, uK_stone[6].y, uK_stone[6].z, uK_stone[6].w);
  ring = sqrt(q) - uK_stone[6].x;
  e = ring + k_zenLump(dx, dy, uK_stone[7].x, uK_stone[7].y, q);
  if (e < core) {
    core = e;
    slope = uK_stone[7].z;
    top = uK_stone[7].w;
  }
  d = k_zenUnion(d, ring - uK_stone[8].x * slow, uK_rake[1].y, uK_rake[1].z);
  float out_v = max(0.0, d);
  float f = max(uK_rake[1].w, uK_rake[2].x - uK_rake[2].y * out_v) + uK_rake[2].z * cos(uK_rake[2].w * out_v + uKF[0].x);
  float g = min(min(uK_rake[3].x - uK_rake[3].y * core, uK_rake[3].z), top - slope * core);
  return max(f, g);
}`;

export const KERNEL_WGSL = `struct KitKernel {
  rake: array<vec4f, 5>,
  stone: array<vec4f, 9>,
  f: array<vec4f, 1>,
}

fn k_zenOval(dx: f32, dy: f32, xx: f32, yy: f32, xy: f32) -> f32 {
  return dx * (dx * xx + dy * xy) + dy * dy * yy;
}

fn k_zenLump(dx: f32, dy: f32, ax: f32, ay: f32, q: f32) -> f32 {
  let p: f32 = ax * dx + ay * dy;
  return p * p * p / (q + 0.000001);
}

fn k_zenUnion(d: f32, r: f32, k0: f32, k1: f32) -> f32 {
  let m: f32 = min(d, r);
  let k: f32 = k0 + k1 * m;
  let h: f32 = max(0.0, k - abs(d - r));
  return m - h * h / (4.0 * k);
}

fn kfield(x: f32, y: f32) -> f32 {
  let v: f32 = kk.rake[0].x * x + kk.rake[0].y * y + kk.rake[0].z;
  let slow: f32 = cos(kk.f[0].y) - kk.rake[4].x;
  var d: f32 = sqrt(v * v + kk.rake[0].w) + kk.rake[1].x + kk.rake[3].w * slow;
  let swell: f32 = cos(kk.f[0].z);
  var dx: f32 = x - kk.stone[0].x;
  var dy: f32 = y - kk.stone[0].y;
  var q: f32 = k_zenOval(dx, dy, kk.stone[0].w, kk.stone[1].x, kk.stone[1].y);
  var ring: f32 = sqrt(q) - kk.stone[0].z;
  var core: f32 = ring + k_zenLump(dx, dy, kk.stone[1].z, kk.stone[1].w, q);
  var slope: f32 = kk.stone[2].x;
  var top: f32 = kk.stone[2].y;
  d = k_zenUnion(d, ring - kk.stone[2].z * swell, kk.rake[1].y, kk.rake[1].z);
  dx = x - kk.stone[2].w;
  dy = y - kk.stone[3].x;
  q = k_zenOval(dx, dy, kk.stone[3].z, kk.stone[3].w, kk.stone[4].x);
  ring = sqrt(q) - kk.stone[3].y;
  var e: f32 = ring + k_zenLump(dx, dy, kk.stone[4].y, kk.stone[4].z, q);
  if (e < core) {
    core = e;
    slope = kk.stone[4].w;
    top = kk.stone[5].x;
  }
  d = k_zenUnion(d, ring - kk.stone[5].y * swell, kk.rake[1].y, kk.rake[1].z);
  dx = x - kk.stone[5].z;
  dy = y - kk.stone[5].w;
  q = k_zenOval(dx, dy, kk.stone[6].y, kk.stone[6].z, kk.stone[6].w);
  ring = sqrt(q) - kk.stone[6].x;
  e = ring + k_zenLump(dx, dy, kk.stone[7].x, kk.stone[7].y, q);
  if (e < core) {
    core = e;
    slope = kk.stone[7].z;
    top = kk.stone[7].w;
  }
  d = k_zenUnion(d, ring - kk.stone[8].x * slow, kk.rake[1].y, kk.rake[1].z);
  let out_v: f32 = max(0.0, d);
  let f: f32 = max(kk.rake[1].w, kk.rake[2].x - kk.rake[2].y * out_v) + kk.rake[2].z * cos(kk.rake[2].w * out_v + kk.f[0].x);
  let g: f32 = min(min(kk.rake[3].x - kk.rake[3].y * core, kk.rake[3].z), top - slope * core);
  return max(f, g);
}`;

